:root {
  font-family: 'DM Sans', sans-serif;
  color: #242320;
  background: #f3f0e9;
  font-synthesis: none;
  --ink: #242320;
  --muted: #77736b;
  --paper: #fbfaf6;
  --line: #dedad1;
  --orange: #e86f4f;
  --orange-dark: #cf583a;
}
* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; min-height: 100vh; background: #f3f0e9; }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; }
.app-shell { min-height: 100vh; display: flex; }
.sidebar { position: fixed; inset: 0 auto 0 0; width: 252px; background: #252724; color: #f5f2eb; padding: 26px 18px 20px; display: flex; flex-direction: column; z-index: 5; }
.brand { display: flex; align-items: center; gap: 11px; padding: 0 7px 25px; font-family: 'Newsreader', serif; font-size: 25px; font-weight: 600; letter-spacing: -.5px; }
.brand-mark { width: 31px; height: 31px; display: grid; place-items: center; background: var(--orange); border-radius: 9px 9px 9px 3px; color: white; transform: rotate(-3deg); }
.brand-mark svg { transform: rotate(3deg); }
.add-button { border: 0; border-radius: 9px; background: var(--orange); color: white; height: 44px; display: flex; align-items: center; justify-content: center; gap: 9px; font-weight: 600; box-shadow: 0 7px 18px rgba(232,111,79,.17); margin: 0 2px 18px; }
.add-button:hover, .save:hover { background: var(--orange-dark); }
.nav-block { display: grid; gap: 4px; }
.nav-item { border: 0; background: transparent; color: #b9bab4; display: flex; align-items: center; gap: 11px; height: 40px; border-radius: 8px; padding: 0 11px; width: 100%; text-align: left; font-size: 14px; }
.nav-item:hover { background: #30322f; color: white; }
.nav-item.active { color: white; background: #383a36; }
.nav-item .count { margin-left: auto; color: #888b84; font-size: 12px; }
.sidebar-heading { color: #777a74; padding: 28px 9px 10px; text-transform: uppercase; letter-spacing: 1.4px; font-size: 10px; font-weight: 700; display: flex; justify-content: space-between; align-items: center; }
.sidebar-heading button { background: none; color: #898b85; border: 0; padding: 2px; }
.collection-dot { height: 8px; width: 8px; border-radius: 3px; margin: 0 5px; }
.sidebar-footer { margin-top: auto; }
.sidebar-footer > button { border: 0; color: #a9aaa5; background: transparent; width: 100%; height: 42px; display: flex; align-items: center; gap: 12px; padding: 0 10px; }
.profile { border-top: 1px solid #3b3d39; margin-top: 12px; padding: 20px 7px 0; display: grid; grid-template-columns: 34px 1fr auto; align-items: center; gap: 10px; }
.avatar { background: #f0c56b; color: #433919; height: 34px; width: 34px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; font-weight: 700; }
.profile strong, .profile span { display: block; }
.profile strong { font-size: 12px; font-weight: 600; }
.profile span { font-size: 10px; color: #858781; margin-top: 2px; }
.profile svg { color: #797b76; }
.content { margin-left: 252px; width: calc(100% - 252px); min-height: 100vh; }
.topbar { height: 76px; border-bottom: 1px solid var(--line); display: flex; justify-content: center; align-items: center; background: rgba(243,240,233,.95); position: sticky; top: 0; z-index: 4; }
.search-wrap { width: min(520px, 55%); height: 42px; border: 1px solid #d4d0c8; background: #faf8f3; border-radius: 10px; display: flex; align-items: center; gap: 10px; padding: 0 12px; color: #8a867f; box-shadow: 0 1px 1px rgba(26,24,18,.03); }
.search-wrap:focus-within { border-color: #aaa59a; box-shadow: 0 0 0 3px rgba(35,34,31,.05); }
.search-wrap input { flex: 1; border: 0; outline: 0; background: transparent; color: var(--ink); font-size: 14px; min-width: 80px; }
.search-wrap input::placeholder { color: #aaa69f; }
kbd { font-family: inherit; background: #eeeae2; border: 1px solid #d9d4cb; border-bottom-width: 2px; border-radius: 5px; padding: 2px 6px; color: #7c776e; font-size: 11px; }
.mobile-add { display:none; }
.page { padding: 45px clamp(30px, 5vw, 76px) 36px; max-width: 1500px; margin: auto; }
.title-row { display: flex; justify-content: space-between; gap: 30px; align-items: flex-end; margin-bottom: 29px; }
.eyebrow { color: var(--orange) !important; font-size: 10px !important; font-weight: 700; letter-spacing: 1.6px; margin: 0 0 7px !important; }
.title-row h1 { font-family: 'Newsreader', serif; font-size: clamp(34px, 4vw, 48px); font-weight: 500; letter-spacing: -1.4px; line-height: .95; margin: 0 0 11px; }
.title-row p { color: #77736b; margin: 0; font-size: 13px; }
.actions { display: flex; gap: 10px; align-items: center; }
.segmented { display: flex; background: #e6e2da; padding: 3px; border-radius: 8px; }
.segmented button { width: 33px; height: 30px; border: 0; background: transparent; border-radius: 6px; color: #8b877f; display: grid; place-items: center; }
