.actions select { height: 36px; min-width: 146px; border: 1px solid #d7d3cb; background: #f9f7f2; border-radius: 8px; color: #625e57; padding: 0 31px 0 11px; font-size: 12px; outline: 0; }
.bookmark-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 19px; }
.bookmark-card { background: var(--paper); border: 1px solid #ddd9d1; border-radius: 13px; overflow: visible; min-width: 0; transition: transform .2s ease, box-shadow .2s ease; position: relative; }
.bookmark-card:hover { transform: translateY(-3px); box-shadow: 0 10px 30px rgba(56,49,39,.09); }
.card-accent { height: 94px; margin: -1px -1px 0; border-radius: 13px 13px 0 0; display: grid; place-items: center; position: relative; background-image: radial-gradient(rgba(255,255,255,.2) 1px, transparent 1px); background-size: 12px 12px; }
.card-accent > span { color: rgba(255,255,255,.94); border: 1px solid rgba(255,255,255,.5); border-radius: 11px; min-width: 43px; height: 43px; padding: 0 9px; display: grid; place-items: center; font-family: 'Newsreader',serif; font-size: 18px; font-weight: 600; background: rgba(255,255,255,.12); backdrop-filter: blur(4px); }
.heart { position: absolute; right: 12px; top: 12px; border: 0; width: 31px; height: 31px; display: grid; place-items: center; color: white; background: rgba(30,28,24,.18); border-radius: 50%; }
.heart:hover { background: rgba(30,28,24,.3); }
.card-body { padding: 18px 18px 15px; }
