.card-title-row { display: grid; grid-template-columns: 1fr auto; gap: 5px; align-items: start; margin-top: 10px; }
.card-title-row a { color: inherit; text-decoration: none; min-width: 0; }
.card-title-row h2 { font-family: 'Newsreader',serif; font-size: 20px; line-height: 1.15; margin: 0; font-weight: 600; letter-spacing: -.25px; }
.card-title-row a:hover h2 { color: var(--orange-dark); }
.more-wrap { position: relative; }
.more { border:0; color:#8e8a83; background:transparent; padding: 1px 0 0 8px; }
.context-menu { position: absolute; z-index: 8; width: 172px; right: -7px; top: 25px; background: #fff; border: 1px solid #ddd9d1; border-radius: 9px; padding: 5px; box-shadow: 0 10px 30px rgba(40,36,28,.16); }
